proc    vision()

{

char     image[256][256];

float    *alfa;                        /* pointer to cab data */

{

while (1) {

get_frame(image);

alfa = reserve(angle);

*alfa = compute_angle(image);

putmes(alfa, angle);

end_cycle();

}

}

