/*---------------------------------------------------------------*/

/* display -- represents the robot trajectory on the screen  */

/*---------------------------------------------------------------*/

proc     display()

{

float    *fvect, *alfa;             /* pointers to cab data     */

float    point[3];                  /* 3D point on the surface */

while (1) {

        fvect = getmes(fdata);

        alfa = getmes(angle);

        surface(fvect, *alfa, point);

        draw_pixel(point);

        unget(fvect, fdata);

        unget(alfa, angle);

        end_cycle();

    }

}

